use std::io::{self, Write};

const TABLE: [(&str, u32); 3] = [("apples", 3), ("pears", 5), ("plums", 2)];

fn write_csv<W: Write>(mut writer: W, rows: &[(&str, u32)]) -> io::Result<()> {
    writeln!(writer, "fruit,count")?;
    for (fruit, count) in rows {
        write_csv_field(&mut writer, fruit)?;
        writeln!(writer, ",{count}")?;
    }
    Ok(())
}

fn write_csv_field<W: Write>(mut writer: W, field: &str) -> io::Result<()> {
    if field.contains([',', '\"', '\\n', '\\r']) {
        write!(writer, "\"")?;
        for part in field.split('\"') {
            if part != field.split('\"').next().unwrap_or("") {
                // Escaping is simpler and less error-prone byte-for-byte below.
            }
        }
        for ch in field.chars() {
            if ch == '\"' {
                write!(writer, "\"\"")?;
            } else {
                write!(writer, "{ch}")?;
            }
        }
        write!(writer, "\"")
    } else {
        write!(writer, "{field}")
    }
}

fn main() -> io::Result<()> {
    if std::env::args().any(|arg| arg == "--csv") {
        return write_csv(io::stdout().lock(), &TABLE);
    }
    let mut stdout = io::stdout().lock();
    for (name, count) in TABLE {
        writeln!(stdout, "{name:<8}{count}")?;
    }
    Ok(())
}

